(()=>{
 let ctx=null,master=null,deviceScheduled=false;
 function context(){if(!ctx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;ctx=new AC();master=ctx.createGain();master.gain.value=.52;master.connect(ctx.destination)}return ctx}
 async function unlock(){const c=context();if(!c)return false;try{if(c.state==='suspended')await c.resume();return c.state==='running'}catch{return false}}
 function tone(c,freq,start,duration,type='sine',volume=.035,endFreq=null){const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,start);if(endFreq)o.frequency.exponentialRampToValueAtTime(endFreq,start+duration);g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(volume,start+.008);g.gain.exponentialRampToValueAtTime(.0001,start+duration);o.connect(g);g.connect(master);o.start(start);o.stop(start+duration+.02)}
 function noise(c,start,duration,volume=.012){const length=Math.ceil(c.sampleRate*duration),buffer=c.createBuffer(1,length,c.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*(1-i/length*.25);const src=c.createBufferSource(),g=c.createGain();src.buffer=buffer;g.gain.setValueAtTime(volume,start);g.gain.exponentialRampToValueAtTime(.0001,start+duration);src.connect(g);g.connect(master);src.start(start);src.stop(start+duration)}
 function brownNoise(c,start,duration,volume=.018){const length=Math.ceil(c.sampleRate*duration),buffer=c.createBuffer(1,length,c.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<length;i++){last=(last+(Math.random()*2-1)*.045)/1.045;data[i]=last*3.1}const src=c.createBufferSource(),filter=c.createBiquadFilter(),g=c.createGain();src.buffer=buffer;filter.type='lowpass';filter.frequency.value=780;filter.Q.value=.7;g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(volume,start+.22);g.gain.setValueAtTime(volume,start+duration-.18);g.gain.exponentialRampToValueAtTime(.0001,start+duration);src.connect(filter);filter.connect(g);g.connect(master);src.start(start);src.stop(start+duration)}
 function vibration(c,start,duration){const o=c.createOscillator(),g=c.createGain(),lfo=c.createOscillator(),depth=c.createGain();o.type='sawtooth';o.frequency.value=62;lfo.type='sine';lfo.frequency.value=7.4;g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(.008,start+.16);g.gain.setValueAtTime(.008,start+duration-.2);g.gain.exponentialRampToValueAtTime(.0001,start+duration);depth.gain.value=.0035;lfo.connect(depth);depth.connect(g.gain);o.connect(g);g.connect(master);o.start(start);lfo.start(start);o.stop(start+duration);lfo.stop(start+duration)}
 async function deviceBuzz(){if(deviceScheduled)return true;if(!(await unlock()))return false;deviceScheduled=true;const c=ctx,t=c.currentTime+.03,d=5.25;tone(c,50,t,d,'sine',.026);tone(c,100,t,d,'sine',.012);tone(c,150,t,d,'sine',.0045);vibration(c,t,d);brownNoise(c,t+.08,d-.12,.018);tone(c,74,t+.05,.16,'square',.018,45);for(let i=0;i<9;i++)tone(c,72+i%2*4,t+.55+i*.51,.075,'sawtooth',.0055,58);tone(c,46,t+4.94,.22,'square',.013,31);return true}
 async function key(){if(!(await unlock()))return;const c=ctx,t=c.currentTime+.002;tone(c,190,t,.045,'square',.032,78);noise(c,t,.035,.018)}
 async function error(){if(!(await unlock()))return;const c=ctx,t=c.currentTime;tone(c,110,t,.14,'sawtooth',.025);tone(c,82,t+.12,.18,'square',.022)}
 document.addEventListener('click',e=>{if(e.target.closest('.word,.bracket,.gate-actions button,#restartHack,.file-link'))key()},true);
 window.TerminalAudio={unlock,deviceBuzz,key,error};
})();
